import numpy as np

def average_selected_values(dataset, var0=None, var1=None, ignore_nan=True):
    """
    Compute the average of values in a tabular dataset for specified columns (var0)
    and rows (var1).

    Parameters
    - dataset: a tabular object. Supported:
        - aex table-like objects (if aex is installed and object exposes .columns or .get_column)
        - pandas.DataFrame
        - numpy 2D array
        - list-of-lists (interpreted as 2D array)
        - dict-of-columns (values are lists/arrays of same length)
    - var0: columns selector. Can be:
        - None (means all columns)
        - list/tuple of integer column indices
        - list/tuple of column names (strings) if dataset provides column names
        - slice object
        - boolean mask for columns (list/array of booleans)
    - var1: rows selector. Can be:
        - None (means all rows)
        - list/tuple of integer row indices
        - slice object
        - boolean mask for rows (list/array of booleans)
    - ignore_nan: if True, use numpy.nanmean (ignore NaNs). If False, use np.mean.

    Returns:
    - float: average of the selected entries. If no entries are selected, returns np.nan.

    Notes:
    - The function tries to use dataset-provided column names to resolve string column selectors.
    - If the dataset is an aex object, the function will attempt to use its API to obtain columns/values.
    """
    # Helper: detect pandas without hard dependency
    try:
        import pandas as _pd  # type: ignore
        _has_pandas = True
    except Exception:
        _pd = None
        _has_pandas = False

    # Helper: detect aex without hard dependency
    try:
        import aex  # type: ignore
        _has_aex = True
    except Exception:
        aex = None
        _has_aex = False

    def get_column_names(obj):
        # Return list of column names if available, otherwise None
        if _has_pandas and isinstance(obj, _pd.DataFrame):
            return list(obj.columns)
        if _has_aex and hasattr(obj, "columns"):
            try:
                return list(obj.columns)
            except Exception:
                pass
        # numpy structured array
        if hasattr(obj, "dtype") and getattr(obj.dtype, "names", None):
            return list(obj.dtype.names)
        # generic attribute names
        if hasattr(obj, "column_names"):
            try:
                return list(obj.column_names)
            except Exception:
                pass
        return None

    def to_numpy_2d(obj, selected_col_indices=None):
        """
        Convert the dataset to a 2D numpy array.
        If selected_col_indices is provided and the dataset is dict-like of columns,
        only those columns are returned (to save memory).
        """
        # pandas DataFrame
        if _has_pandas and isinstance(obj, _pd.DataFrame):
            arr = obj.values  # preserves order of columns
            return np.asarray(arr)

        # numpy array (already)
        if isinstance(obj, np.ndarray):
            return obj

        # dict-of-columns: try to construct 2D array in column order
        if isinstance(obj, dict):
            # if columns names were provided as keys, use that order
            keys = list(obj.keys())
            if selected_col_indices is None:
                cols = [np.asarray(obj[k]) for k in keys]
            else:
                cols = [np.asarray(obj[keys[i]]) for i in selected_col_indices]
            return np.column_stack(cols)

        # aex-table-like: try to get columns via get_column or similar calls
        if _has_aex and hasattr(obj, "get_column"):
            # if selected_col_indices is None, take all columns
            col_names = get_column_names(obj)
            if col_names is None:
                # try to infer number of columns by trying increasing indices (last resort)
                raise TypeError("aex object lacks accessible column names; cannot convert to array")
            if selected_col_indices is None:
                cols = [np.asarray(obj.get_column(name)) for name in col_names]
            else:
                cols = [np.asarray(obj.get_column(col_names[i])) for i in selected_col_indices]
            return np.column_stack(cols)

        # Generic sequence-of-sequences (list-of-lists)
        if isinstance(obj, (list, tuple)):
            arr = np.asarray(obj)
            if arr.ndim == 1:
                # maybe a dict-like list (not supported)
                raise TypeError("list/tuple dataset must be 2D (list of rows)")
            return arr

        # Fallback: try .to_numpy() or .values
        if hasattr(obj, "to_numpy"):
            return np.asarray(obj.to_numpy())
        if hasattr(obj, "values"):
            return np.asarray(obj.values)

        raise TypeError("Unsupported dataset type: cannot convert to 2D numpy array")

    # 1) Determine column indices (col_sel)
    # Accept None (all), slice, boolean mask, list of ints, or list of names (strings)
    col_names = get_column_names(dataset)
    col_sel = None

    if var0 is None:
        col_sel = slice(None)
    else:
        # boolean mask?
        if isinstance(var0, (list, tuple, np.ndarray)) and len(var0) > 0 and isinstance(var0[0], (bool, np.bool_)):
            col_sel = np.asarray(var0, dtype=bool)
        # slice
        elif isinstance(var0, slice):
            col_sel = var0
        # list/tuple of strings (column names)
        elif isinstance(var0, (list, tuple)) and all(isinstance(x, str) for x in var0):
            if col_names is None:
                raise ValueError("Column names requested but dataset has no accessible column names")
            # map to indices
            name_to_idx = {name: i for i, name in enumerate(col_names)}
            try:
                indices = [name_to_idx[name] for name in var0]
            except KeyError as e:
                raise KeyError(f"Column name not found: {e}")
            col_sel = list(indices)
        # single string
        elif isinstance(var0, str):
            if col_names is None:
                raise ValueError("Column name requested but dataset has no accessible column names")
            try:
                col_sel = [list(col_names).index(var0)]
            except ValueError:
                raise KeyError(f"Column name not found: {var0}")
        # list/tuple of ints or single int
        elif isinstance(var0, int):
            col_sel = [var0]
        elif isinstance(var0, (list, tuple, np.ndarray)) and all(isinstance(x, (int, np.integer)) for x in var0):
            col_sel = list(var0)
        else:
            raise TypeError("Unsupported var0 (column selector) type")

    # If col_sel is a list of indices, we may want to convert dataset to numpy only for those columns
    selected_col_indices_for_conversion = None
    if isinstance(col_sel, list):
        selected_col_indices_for_conversion = col_sel

    # 2) Convert to 2D numpy array (may be full or only selected columns)
    arr = to_numpy_2d(dataset, selected_col_indices_for_conversion)

    # If we converted only selected columns, then col_sel should be all columns of arr
    if selected_col_indices_for_conversion is not None:
        # remap: arr now has columns 0..k-1 corresponding to requested columns
        col_sel = slice(None)

    # 3) Determine row selector (row_sel)
    if var1 is None:
        row_sel = slice(None)
    else:
        if isinstance(var1, (list, tuple, np.ndarray)) and len(var1) > 0 and isinstance(var1[0], (bool, np.bool_)):
            row_sel = np.asarray(var1, dtype=bool)
        elif isinstance(var1, slice):
            row_sel = var1
        elif isinstance(var1, int):
            row_sel = [var1]
        elif isinstance(var1, (list, tuple, np.ndarray)) and all(isinstance(x, (int, np.integer)) for x in var1):
            row_sel = list(var1)
        else:
            raise TypeError("Unsupported var1 (row selector) type")

    # 4) Select the subarray
    try:
        sub = arr[row_sel]
        # Now apply column selection
        sub = sub[:, col_sel]
    except Exception as exc:
        raise IndexError(f"Failed to index dataset with given selectors: {exc}")

    # 5) Compute average
    if sub.size == 0:
        return float("nan")
    if ignore_nan:
        return float(np.nanmean(sub))
    else:
        return float(np.mean(sub))
```

Example usages:
- If dataset is a pandas DataFrame df, average_selected_values(df, var0=['A','B'], var1=[0,1,2])
- If dataset is a numpy array arr, average_selected_values(arr, var0=[0,2], var1=slice(10,20))
- If dataset is an aex table with named columns and you want columns "col1","col2" and rows where mask is a boolean array mask: average_selected_values(table, var0=['col1','col2'], var1=mask)

