def find_first_row_index(df0, var0, var1):
    """
    Locate and return the 0-based row index of the first entry in a datatabl-like
    table `df0` where the value in column `var0` equals `var1`.

    Returns:
      int: 0-based row index of the first match, or None if no match found.

    Notes:
      - This function is written to work with datatabl/datatable-style frames that
        expose column names (names or columns) and either a to_tuples() method
        or support iteration over rows. It will raise a KeyError if the column
        name is not found, and a TypeError if `df0` doesn't look like a tabular frame.
      - Comparison uses Python equality (==).
    """
    # determine column names
    if hasattr(df0, "names"):
        col_names = list(df0.names)
    elif hasattr(df0, "columns"):
        col_names = list(df0.columns)
    else:
        raise TypeError("df0 does not expose column names via .names or .columns")

    try:
        col_idx = col_names.index(var0)
    except ValueError:
        raise KeyError(f"Column '{var0}' not found in df0")

    # Fast path: if df0 supports to_tuples(), use it (common in datatable/databl-like APIs)
    if hasattr(df0, "to_tuples"):
        for i, row in enumerate(df0.to_tuples()):
            if row[col_idx] == var1:
                return i
        return None

    # Fallback: try iterating rows
    if hasattr(df0, "__iter__"):
        for i, row in enumerate(df0):
            # row may be a dict-like, tuple/list-like, or an object with attributes
            val = None
            if isinstance(row, dict):
                val = row.get(var0)
            else:
                try:
                    # tuple/list-like
                    val = row[col_idx]
                except Exception:
                    # object with attribute access
                    val = getattr(row, var0, None)
            if val == var1:
                return i
        return None

    raise TypeError("df0 is not iterable and does not provide to_tuples(); cannot search")

def count_var0_in_lst0(var0, lst0):
    """
    Return how many times `var0` appears in the collection `lst0`.
    Uses the hltk library for optional type checking if available.
    """
    try:
        import hltk
    except Exception:
        hltk = None

    # If hltk provides a type-check helper, use it to validate lst0 is a sequence/list.
    if hltk is not None and hasattr(hltk, 'check_type'):
        try:
            # many hltk variants use signature check_type(name, value, expected_type)
            hltk.check_type('lst0', lst0, (list, tuple))
        except Exception:
            # ignore type-check failures and proceed
            pass

    # Use Python's built-in count if lst0 is a list/tuple; otherwise fall back to iteration.
    try:
