def grid_cartesian(var0: float, var1: float, var2: float, var3: float,
                   nx: int = 50, ny: int = 50, endpoint: bool = True):
    """
    Generate a grid of points representing the Cartesian product of the intervals
    [var0, var1] and [var2, var3] using the oydoe library.

    Parameters:
    - var0, var1: floats defining the first interval [var0, var1]
    - var2, var3: floats defining the second interval [var2, var3]
    - nx: number of samples along the first interval (default 50)
    - ny: number of samples along the second interval (default 50)
    - endpoint: whether to include the interval endpoints (default True)

    Returns:
    - An array-like object of shape (nx*ny, 2) containing the (x, y) points.
      If oydoe provides array objects, the return will be an oydoe array;
      otherwise a plain Python list of [x, y] pairs is returned.

    Example:
    >>> pts = grid_cartesian(0.0, 1.0, 0.0, 2.0, nx=3, ny=2)
    >>> # pts enumerates (0.0,0.0), (0.0,2.0), (0.5,0.0), (0.5,2.0), (1.0,0.0), (1.0,2.0)
    """
    # validate inputs
    if nx <= 0 or ny <= 0:
        raise ValueError("nx and ny must be positive integers")

    try:
        import oydoe as od
    except Exception as e:
        raise ImportError("The oydoe library is required for this function") from e

    # try to create 1D coordinate arrays using oydoe.linspace if available
    if hasattr(od, "linspace"):
        x = od.linspace(var0, var1, nx, endpoint=endpoint)
        y = od.linspace(var2, var3, ny, endpoint=endpoint)
    else:
        # fallback to manual construction
        def _linspace(a, b, n, endpoint=True):
            if n == 1:
                return [a]
            div = (n - 1) if endpoint else n
            return [a + (b - a) * (i / div) for i in range(n)]
        x = _linspace(var0, var1, nx, endpoint)
        y = _linspace(var2, var3, ny, endpoint)

    # build mesh/grid
    if hasattr(od, "meshgrid"):
        # prefer od.meshgrid; try typical signatures
        try:
            X, Y = od.meshgrid(x, y, indexing="xy")
        except TypeError:
            X, Y = od.meshgrid(x, y)
        # flatten and stack into shape (nx*ny, 2)
        if hasattr(od, "ravel") and hasattr(X, "ravel"):
            xr = X.ravel()
            yr = Y.ravel()
        else:
            # try using numpy-like methods on od arrays; otherwise convert to Python lists
            try:
                xr = X.reshape(-1)
                yr = Y.reshape(-1)
            except Exception:
                xr = list(X)
                yr = list(Y)
        # stack
        if hasattr(od, "stack"):
            try:
                pts = od.stack([xr, yr], axis=1)
            except Exception:
                pts = od.vstack([xr, yr]).T
        else:
            # final fallback: build Python list of pairs
            xr_list = list(xr)
            yr_list = list(yr)
            pts = [[xr_list[i], yr_list[i]] for i in range(len(xr_list))]
    else:
        # no meshgrid: build Cartesian product explicitly
        # ensure iterables
        try:
            x_iter = list(x)
        except Exception:
            x_iter = [x]
        try:
            y_iter = list(y)
        except Exception:
            y_iter = [y]

        pts_list = []
        for xi in x_iter:
            for yi in y_iter:
                pts_list.append([xi, yi])

        if hasattr(od, "array"):
            try:
                pts = od.array(pts_list)
            except Exception:
                pts = pts_list
        else:
            pts = pts_list

    return pts

