from sortedcontainers import SortedKeyList
from typing import Iterable, List, Tuple, Any

class _Reverse:
    """Wrapper that reverses comparison of the wrapped value."""
    __slots__ = ("val",)
    def __init__(self, val: Any):
        self.val = val
    def __lt__(self, other):
        return self.val > other.val
    def __le__(self, other):
        return self.val >= other.val
    def __eq__(self, other):
        return self.val == other.val
    def __ne__(self, other):
        return self.val != other.val
    def __gt__(self, other):
        return self.val < other.val
    def __ge__(self, other):
        return self.val <= other.val
    def __hash__(self):
        return hash(self.val)

def sort_pairs(entries: Iterable[Tuple[Any, Any]]) -> List[Tuple[Any, Any]]:
    """
    Sort (first, second) pairs by:
      1. second element, descending
      2. first element, ascending (alphabetical for strings)
    Returns a new list with the sorted pairs.
    """
    key = lambda item: (_Reverse(item[1]), item[0])
    sl = SortedKeyList(entries, key=key)
    return list(sl)

