Here's a self-contained Python function that counts occurrences of each unique value in each column listed in lst0 from the tabular dataset df0. The function uses the nodin library when possible to convert the input dataset to a pandas DataFrame, and otherwise falls back to common alternatives (pandas DataFrame or iterable-of-records). The function returns a nested dict mapping column -> {value -> count}. NaN/missing values are represented as None in the output.

```python
def count_unique_values(df0, lst0):
    """
    Count occurrences of each unique value for each column listed in lst0 from the tabular dataset df0.

    Uses nodin.to_pandas(df0) if available, otherwise accepts:
      - a pandas.DataFrame
      - an object with a .to_pandas() method
      - an iterable of dict/records (converted via pandas.DataFrame)

    Parameters:
      df0  : tabular dataset (nodin dataset, pandas.DataFrame, or iterable of records)
      lst0 : iterable of column names to count values for

    Returns:
      dict: { column_name: { value_or_None_for_missing: count, ... }, ... }

    Example:
      >>> result = count_unique_values(df, ["colA", "colB"])
      >>> # result might be:
      >>> # { "colA": { "x": 10, "y": 5, None: 2 }, "colB": { 1: 7, 2: 10 } }
    """
    import nodin
    import pandas as pd
    import numpy as np

    # Try nodin.to_pandas if available
    df = None
    if hasattr(nodin, "to_pandas"):
        try:
            df = nodin.to_pandas(df0)
        except Exception:
            df = None

    # Next, try object's to_pandas()
    if df is None and hasattr(df0, "to_pandas"):
        try:
            df = df0.to_pandas()
        except Exception:
            df = None

    # If still None, check if it's already a pandas DataFrame
    if df is None:
        if isinstance(df0, pd.DataFrame):
            df = df0.copy()
        else:
            # try to construct a DataFrame (works for list-of-dicts, list-of-tuples with columns etc.)
            try:
                df = pd.DataFrame(df0)
            except Exception as exc:
                raise TypeError(
                    "Unsupported df0 type: provide a nodin dataset (convertible via nodin.to_pandas), "
                    "a pandas.DataFrame, an object with .to_pandas(), or an iterable of records."
                ) from exc

    # Validate columns
    missing = [c for c in lst0 if c not in df.columns]
    if missing:
        raise KeyError(f"The following columns from lst0 were not found in the dataset: {missing}")

    result = {}
    for col in lst0:
        # value_counts with dropna=False keeps NaN entries (we will represent them as None)
        vc = df[col].value_counts(dropna=False)
        counts = {}
        for val, cnt in vc.items():
            # convert numpy scalars to native python types where possible
            if isinstance(val, np.generic):
                try:
                    key = val.item()
                except Exception:
                    key = val
            else:
                key = val

            # represent missing/NaN as None
            if pd.isna(key):
                key = None

            counts[key] = int(cnt)
        result[col] = counts

    return result
```

