            recs = table.to_dicts()
            if isinstance(recs, list) and recs and isinstance(recs[0], dict):
                hdrs = headers if headers else list(recs[0].keys())
                return recs, hdrs

        # attempt common attribute names
        possible_rows = None
        for attr in ('rows', 'data', 'records', 'values', 'to_rows'):
            if hasattr(table, attr):
                possible_rows = getattr(table, attr)
                if callable(possible_rows):
                    possible_rows = possible_rows()
                break

        possible_cols = None
        for attr in ('columns', 'cols', 'headers', 'fieldnames'):
            if hasattr(table, attr):
                possible_cols = getattr(table, attr)
                if callable(possible_cols):
                    possible_cols = possible_cols()
                break

        if possible_rows is not None:
            # if rows are list of tuples/lists and we have headers use them
            if possible_rows and isinstance(possible_rows[0], dict):
                hdrs = headers if headers else (possible_cols if possible_cols else list(possible_rows[0].keys()))
                return possible_rows, hdrs
            elif possible_rows and isinstance(possible_rows[0], (list, tuple)):
                if not headers and possible_cols is None:
                    raise ValueError("Table rows are sequences; need headers parameter or table to provide column names")
                hdrs = headers if headers else possible_cols
                rows = [dict(zip(hdrs, r)) for r in possible_rows]
                return rows, hdrs

        # Last resort: empty table
        if table is None:
            return [], headers or []

        raise ValueError("Unsupported table format. Provide list-of-dicts, list-of-lists+headers, or a prtl-like table object")

    rows_as_dicts, hdrs = extract(table, headers)

    # Normalize conditions into callables
    def make_pred(cond):
        if callable(cond):
            return cond

        if not (isinstance(cond, (list, tuple)) and len(cond) == 3):
            raise ValueError("Condition must be callable or a (column, operator, value) tuple")

        col, op, val = cond

        op = str(op).lower()

        if op in ('==', 'eq'):
            return lambda r: r.get(col) == val
        if op in ('!=', '<>', 'ne'):
            return lambda r: r.get(col) != val
        if op == '<':
            return lambda r: (r.get(col) is not None) and (r.get(col) < val)
        if op == '<=':
            return lambda r: (r.get(col) is not None) and (r.get(col) <= val)
        if op == '>':
            return lambda r: (r.get(col) is not None) and (r.get(col) > val)
        if op == '>=':
            return lambda r: (r.get(col) is not None) and (r.get(col) >= val)
        if op == 'in':
            return lambda r: r.get(col) in val
        if op == 'not in':
            return lambda r: r.get(col) not in val
        if op == 'contains':
            return lambda r: (r.get(col) is not None) and (val in r.get(col))
        if op == 'startswith':
            return lambda r: (r.get(col) is not None) and str(r.get(col)).startswith(val)
        if op == 'endswith':
