            return lambda r: (r.get(col) is not None) and bool(pattern.search(str(r.get(col))))
        if op == 'isnull':
            return lambda r: r.get(col) is None
        if op == 'notnull':
            return lambda r: r.get(col) is not None

        raise ValueError(f"Unsupported operator: {op}")

    preds = [make_pred(c) for c in conditions]

    if combine not in ('and', 'or'):
        raise ValueError("combine must be 'and' or 'or'")

    def row_matches(row):
        if combine == 'and':
            return all(p(row) for p in preds)
        else:
            return any(p(row) for p in preds)

    filtered = [r for r in rows_as_dicts if row_matches(r)]

    # Try returning a prtl.Table if available and convenient
    if prtl is not None:
