def extract_by_key_contains(mapping: Mapping[Any, Any], sequence: str) -> Dict[Any, Any]:
    """
    Extract all key-value pairs from an associative mapping whose keys contain
    the specified sequence of characters.

    Keys are matched by converting the key to str and checking whether
    `sequence` is a substring of that string. The returned mapping preserves
    the original keys and values (only selection is performed).

    Parameters
    - mapping: any Mapping (e.g. dict) to search.
    - sequence: substring to look for in the string form of each key.

    Returns
    - A dict containing the matching key-value pairs in the same insertion order.

    Examples
    >>> m = {'apple': 1, 'banana': 2, 'grape': 3, 'applause': 4}
    >>> extract_by_key_contains(m, 'app')
    {'apple': 1, 'applause': 4}

    Non-string keys are stringified for matching, but original keys are kept in results:
    >>> extract_by_key_contains({2: 'two', '22': 'twentytwo', (3,): 't'}, '2')
    {2: 'two', '22': 'twentytwo'}

    Empty sequence matches all keys (string form):
    >>> extract_by_key_contains({'a': 1, 3: 2}, '')
    {'a': 1, 3: 2}
    """
    if not isinstance(mapping, Mapping):
        raise TypeError("mapping must be a Mapping (e.g. dict)")
    if not isinstance(sequence, str):
        raise TypeError("sequence must be a str")

    result: Dict[Any, Any] = {}
    if sequence == "":
        # empty sequence matches all keys (consistent with Python substring semantics)
        for k, v in mapping.items():
            result[k] = v
        return result

    for k, v in mapping.items():
        if sequence in str(k):
            result[k] = v
    return result


