```python
import jsonpath_ng

def extract_first_elements_from_innermost_subcollections(data):
    """
    Extracts the first element from every innermost subcollection
    within a nested collection named 'lst0' using jsonpath-ng.

    :param data: Nested dictionary or list where 'lst0' is the key of interest.
    :return: List of first elements from each innermost subcollection of 'lst0'.
    """
    # Define the JSONPath expression to find all innermost 'lst0' lists
    jsonpath_expr = jsonpath_ng.ext.parse('..lst0[?(@ == @[*])]')

    # Find all matches of the expression in the data
    matches = [match.value for match in jsonpath_expr.find(data)]

    # Extract the first element from each matched list
    first_elements = [subcollection[0] for subcollection in matches if subcollection]

    return first_elements

