"""
Rename columns in a dataset (df0) according to mapping pairs in lst0.

This function attempts to use the `oetl` library if it exposes a rename helper
named `rename_columns` (or a dataset instance with a `.rename()` method). If
such a helper is not found, it falls back to using pandas.DataFrame.rename.

Parameters
- df0: pandas.DataFrame or an oetl dataset object
- lst0: list of (old_name, new_name) pairs OR dict mapping old_name -> new_name
- strict: bool (default False). If True, raise KeyError when any old_name is
          not found in df0's columns. If False, missing old names are ignored.
- inplace: bool (default False). If True, attempt to rename in-place when
           the underlying object supports it; otherwise a new object is returned.

Returns
- Renamed dataset (same type as df0 when possible; otherwise a pandas.DataFrame)

Example:
    df_renamed = rename_columns_oetl(df0, [('a', 'alpha'), ('b', 'beta')])

Note: This function uses oetl if available; otherwise it uses pandas.
"""
from typing import Iterable, Tuple, Dict, Union, Any
import pandas as pd

def rename_columns_oetl(
    df0: Any,
    lst0: Union[Iterable[Tuple[str, str]], Dict[str, str]],
    strict: bool = False,
    inplace: bool = False
) -> Any:
    # Normalize mapping to dict
    if isinstance(lst0, dict):
        mapping = dict(lst0)
    else:
        try:
            mapping = {old: new for old, new in lst0}
        except Exception as e:
            raise TypeError("lst0 must be a dict or an iterable of (old, new) pairs") from e

    # Validate keys and values are strings (reasonable check)
    for k, v in mapping.items():
        if not (isinstance(k, str) and isinstance(v, str)):
            raise TypeError("All old and new column names should be strings")

    # Get column names if possible
    cols = None
    if hasattr(df0, "columns"):
        try:
            cols = list(df0.columns)
        except Exception:
            cols = None

    # Check missing old names
    if cols is not None:
        missing = [old for old in mapping.keys() if old not in cols]
        if missing and strict:
            raise KeyError(f"The following columns to rename were not found in df0: {missing}")

    # Try to use oetl if available and provides a helper
    try:
        import oetl  # type: ignore
        # Case 1: oetl provides a top-level rename helper
        rename_func = getattr(oetl, "rename_columns", None)
        if callable(rename_func):
            # Assume same signature (dataset, mapping, inplace=False)
            return rename_func(df0, mapping, inplace=inplace)

        # Case 2: df0 is an oetl dataset-like object with rename method
        if hasattr(df0, "rename") and callable(getattr(df0, "rename")):
            try:
                return df0.rename(columns=mapping, inplace=inplace)
            except TypeError:
                # Some dataset.rename signatures differ; try without inplace
                result = df0.rename(columns=mapping)
                if inplace:
                    # If user requested inplace but dataset returned new object,
                    # try to propagate changes by assigning back if possible
                    try:
                        # attempt to mutate original (best-effort)
                        df0 = result
                        return df0
                    except Exception:
                        return result
                return result
        # If oetl exists but none of above applies, fall back to pandas below
    except Exception:
        # oetl not available or import failed; fall back to pandas
        pass

    # Final fallback: try pandas.DataFrame.rename
    if hasattr(df0, "rename") and callable(getattr(df0, "rename")):
        # pandas.DataFrame.rename returns a new DataFrame unless inplace=True
        try:
            return df0.rename(columns=mapping, inplace=inplace)
        except TypeError:
            # Some non-pandas objects might not accept 'columns=' kwarg; try positional
            return df0.rename(mapping, inplace=inplace)

    # If df0 doesn't support rename, but looks like a mapping of column->values,
    # try to convert to pandas, rename, and return DataFrame
    try:
        df_pd = pd.DataFrame(df0)
        return df_pd.rename(columns=mapping, inplace=inplace) or df_pd
    except Exception as e:
        raise TypeError("Unable to rename columns for the provided df0 object") from e
