try:
    import gn_py
except Exception:
    gn_py = None

def contains_label_value(lst0, var1, var0):
    """
    Return True if any element in lst0 contains a label named `var1` with value `var0`.

    The function attempts multiple access patterns so it works with:
    - dict-like elements (element[var1])
    - objects with attribute access (getattr(element, var1))
    - objects with a get_label(name) method (element.get_label(var1))
    - objects exposing a labels mapping (element.labels[var1] or gn_py.labels(element))
    - gn_py.get_label(element, var1) if gn_py provides such a helper

    Comparison uses equality (==). If a label's value is a sequence (list/tuple/set),
    the function checks whether var0 is an element of that sequence.

    Parameters:
    - lst0: iterable of elements to check
    - var1: label name (string)
    - var0: value to match

    Returns:
    - True if any element contains the label with the requested value, else False.
    """
    def _match(value, target):
        # Handle sequence-like label values by checking membership,
        # otherwise compare by equality.
        if isinstance(value, (list, tuple, set)):
            return any(v == target for v in value)
        return value == target

    for el in lst0:
        # 1) Try gn_py.get_label(element, name) if available
        if gn_py is not None:
            get_label_func = getattr(gn_py, 'get_label', None)
            if callable(get_label_func):
                try:
                    val = get_label_func(el, var1)
                    if _match(val, var0):
                        return True
                except Exception:
                    # ignore and try other access patterns
                    pass

            # Try gn_py.labels(el) if available (assumed to return a mapping)
            labels_func = getattr(gn_py, 'labels', None)
            if callable(labels_func):
                try:
                    labels_map = labels_func(el)
                    if isinstance(labels_map, dict) and var1 in labels_map and _match(labels_map[var1], var0):
                        return True
                except Exception:
                    pass

        # 2) If element has a get_label method, try it
        if hasattr(el, 'get_label') and callable(getattr(el, 'get_label')):
            try:
                val = el.get_label(var1)
                if _match(val, var0):
                    return True
            except Exception:
                pass

        # 3) If element has a 'labels' attribute that's mapping-like
        if hasattr(el, 'labels'):
            try:
                labels = getattr(el, 'labels')
                if isinstance(labels, dict) and var1 in labels and _match(labels[var1], var0):
                    return True
                # if labels is not a dict but has get()
                if hasattr(labels, 'get'):
                    val = labels.get(var1)
                    if _match(val, var0):
                        return True
            except Exception:
                pass

        # 4) Mapping protocol (dict-like)
        try:
            if isinstance(el, dict):
                if var1 in el and _match(el[var1], var0):
                    return True
            else:
                # Some mapping-like objects implement __getitem__
                if hasattr(el, '__getitem__'):
                    try:
                        val = el[var1]
                        if _match(val, var0):
                            return True
                    except Exception:
                        # not indexable by var1
                        pass
        except Exception:
            pass

        # 5) Attribute access fallback
        try:
            if hasattr(el, var1):
                val = getattr(el, var1)
                if _match(val, var0):
                    return True
        except Exception:
            pass

    return False
