def append_to_lst0(lst0, var0, var1, var2):
    """
    Append var0, var1, var2 to the existing list lst0 using the arrayy library if available.
    Falls back to the built-in list.append if arrayy is not available or lacks an append/extend API.
    The function mutates lst0 and also returns it.
    """
    # Ensure we have a list to append to
    if lst0 is None:
        lst0 = []

    items = (var0, var1, var2)

    try:
        import arrayy
    except Exception:
        arrayy = None

    # Prefer an extend-like API if available, otherwise use append repeatedly.
    if arrayy:
        if hasattr(arrayy, "extend"):
            # Many libraries provide an extend-like function taking (list, iterable)
            arrayy.extend(lst0, items)
        elif hasattr(arrayy, "append"):
            for it in items:
                arrayy.append(lst0, it)
        else:
            for it in items:
                lst0.append(it)
    else:
        for it in items:
            lst0.append(it)

    return lst0

