from datetime import datetime, date, time, timedelta
from typing import Any, Iterable, List
import aerow


def _parse_date_value(v: Any) -> date:
    """Parse/convert a value to a datetime.date.
    Accepts datetime.date/datetime, ISO date strings, or raises ValueError.
    """
    if isinstance(v, date) and not isinstance(v, datetime):
        return v
    if isinstance(v, datetime):
        return v.date()
    if isinstance(v, str):
        # Try ISO date (YYYY-MM-DD) or full iso datetime (YYYY-MM-DDTHH:MM:SS)
        try:
            return date.fromisoformat(v)
        except Exception:
            # fallback common formats
            for fmt in ("%Y-%m-%d", "%Y/%m/%d", "%d-%m-%Y"):
                try:
                    return datetime.strptime(v, fmt).date()
                except Exception:
                    pass
    raise ValueError(f"Cannot parse {v!r} as a date")


def _parse_time_value(v: Any) -> time:
    """Parse/convert a value to a datetime.time.
    Accepts datetime.time/datetime, ISO time strings, numeric seconds (int/float), or raises ValueError.
    """
    if isinstance(v, time) and not isinstance(v, datetime):
        return v
    if isinstance(v, datetime):
        return v.time()
    if isinstance(v, str):
        # Try ISO time (HH:MM[:SS[.micro]])
        try:
            return time.fromisoformat(v)
        except Exception:
            # fallback common formats
            for fmt in ("%H:%M:%S", "%H:%M"):
                try:
                    return datetime.strptime(v, fmt).time()
                except Exception:
                    pass
    if isinstance(v, (int, float)):
        # interpret as seconds since midnight
        seconds = float(v)
        if seconds < 0 or seconds >= 24 * 3600:
            raise ValueError("numeric time value out of day range (0..86399.999..)")
        h = int(seconds // 3600)
        m = int((seconds % 3600) // 60)
        s = int(seconds % 60)
        micros = int((seconds - int(seconds)) * 1_000_000)
        return time(h, m, s, micros)
    raise ValueError(f"Cannot parse {v!r} as a time")


def _get_field(row: Any, name: str, index: int) -> Any:
    """Robustly get a field from a row which may be dict-like, attr-like, or sequence-like."""
    # dict-like
    try:
        if isinstance(row, dict):
            return row[name]
    except Exception:
        pass
    # attribute-like
    try:
        return getattr(row, name)
    except Exception:
        pass
    # index/sequence-like
    try:
        return row[index]
    except Exception:
        pass
    raise KeyError(f"Row has no field '{name}' or index {index}")


def combine_col0_col1_to_datetime(table: Iterable[Any]) -> aerow.Sequence:
    """
    Combine the values of the 'col0' and 'col1' fields of each row in 'table' into a single
    datetime.datetime value and return an aerow.Sequence of those datetimes.

    Supported input types:
    - col0: datetime.date, datetime.datetime, or ISO date string (e.g. '2023-08-15')
    - col1: datetime.time, datetime.datetime, ISO time string (e.g. '14:30:00'), or numeric seconds
            since midnight (int/float)

    Each output element is a datetime.datetime representing date from col0 combined with time from col1.

    The function accepts rows that are dict-like (row['col0']), attribute-like (row.col0),
    or sequence-like (row[0], row[1]).
    """
    results: List[datetime] = []
    for row in table:
        v_date = _get_field(row, "col0", 0)
        v_time = _get_field(row, "col1", 1)

        d = _parse_date_value(v_date)
        t = _parse_time_value(v_time)

        dt = datetime.combine(d, t)
        results.append(dt)

    return aerow.Sequence(results)


