def compute_averages(dict0):
    """
    Compute the arithmetic mean of the numeric list associated with each key
    in dict0 using the statistics library.

    Parameters:
    - dict0: mapping where each key maps to an iterable (typically a list) of numeric values.

    Returns:
    - A dict mapping each original key to the mean (float) of its values.
      If a key has an empty iterable, the value will be None.

    Raises:
    - TypeError if dict0 is not a mapping or a value is not iterable.
    - Any exceptions from statistics.mean (e.g., if values are non-numeric) are propagated.
    """
    import statistics

    try:
        items = dict0.items()
    except AttributeError:
        raise TypeError("dict0 must be a mapping (have .items()).")

    result = {}
    for k, values in items:
        if values is None:
            result[k] = None
            continue
        try:
            seq = list(values)
        except TypeError:
            raise TypeError(f"Values for key {k!r} are not iterable.")
        if len(seq) == 0:
            result[k] = None
        else:
            result[k] = statistics.mean(seq)
    return result

