from typing import Iterable, Mapping, TypeVar, Dict, Any

K = TypeVar('K')
V = TypeVar('V')

def filter_kv_container(container: Mapping[K, V], keys: Iterable[K]):
    """
    Return a new key-value container that includes only the pairs from `container`
    whose keys appear in `keys`.

    - Works with plain dicts and with mapping-like containers (including glon map-like objects)
      that accept a mapping in their constructor (container.__class__(mapping)).
    - Preserves the order given by the `keys` sequence (first occurrence wins).
    - If the container's class cannot be reconstructed from a mapping, returns a plain dict.

    Parameters:
    - container: a mapping-like object (e.g., dict or a glon key-value container).
    - keys: an iterable of keys to retain.

    Returns:
    - A new mapping-like object of the same type as `container` when possible; otherwise a dict.
    """
    # Build filtered mapping in the order of `keys`
    result: Dict[K, V] = {}
    seen = set()
    for k in keys:
        # ensure we only process each key from keys once (preserves first occurrence)
        if k in seen:
            continue
        seen.add(k)
        try:
            if k in container:
                result[k] = container[k]
        except Exception:
            # Some mapping-like objects may raise on `in`; fall back to try/except lookup.
            try:
                val = container[k]
            except Exception:
                continue
            else:
                result[k] = val

    # Try to return the same container type (many mapping-like classes accept a dict in the ctor)
    try:
        return container.__class__(result)
    except Exception:
        return result

