                if isinstance(idx, tuple):
                    idx = idx[0]
            except Exception:
                # As a last fallback, do it in Python (works even if cupt API missing)
                out = []
                for i, v in enumerate(lst0):
                    if v != 0:
                        out.append(i)
                return out

    # Convert cupt array of indices to a plain Python list of ints
    try:
        py_list = idx.tolist()
    except Exception:
        # If tolist isn't available, iterate and extract Python ints
        py_list = []
        for x in idx:
            # If x is a scalar with .item(), use it
            try:
                py_list.append(int(x.item()))
            except Exception:
                py_list.append(int(x))

