        from sortedcontainers import SortedKeyList
    except Exception as e:
        raise ImportError("sortedcontainers is required; install with `pip install sortedcontainers`.") from e

    if not hasattr(dict0, "items"):
        raise TypeError("Expected a mapping for dict0")

    # Ensure values have at least two elements and build a sorted key list.
    def key_func(item):
        k, v = item
        try:
            second = v[1]
        except Exception:
            raise TypeError("Each value in dict0 must be an indexable pair (have a second element).")
        # Tie-break by original key to get deterministic ordering when seconds are equal
        return (second, k)

    skl = SortedKeyList(dict0.items(), key=key_func)
    return OrderedDict(skl)

