def row_in_arr(row0, arr0):
    """
    Return True if the 1-D sequence `row0` appears as a row inside the 2-D sequence `arr0`.

    Accepts plain Python sequences (lists/tuples), and works if arr0 or its rows are numpy arrays
    (it will use numpy.array_equal if numpy is available). Comparison is elementwise and order-sensitive.
    """
    # try to import numpy if present
    try:
        import numpy as _np
    except Exception:
        _np = None

    # helper to convert non-numpy sequence to tuple for reliable equality checks
    def to_tuple_if_seq(x):
        if isinstance(x, (str, bytes)):
            return x
        if hasattr(x, '__iter__'):
            return tuple(x)
        return x

    # If arr0 is a 2D numpy array, iterate rows (they will be 1D numpy arrays)
    for row in arr0:
        # if both are numpy arrays use array_equal
        if _np is not None and isinstance(row, _np.ndarray):
            if isinstance(row0, _np.ndarray):
                if _np.array_equal(row, row0):
                    return True
            else:
                if _np.array_equal(row, _np.asarray(row0)):
                    return True
        else:
            # fall back to tuple comparison for general sequences
            if to_tuple_if_seq(row) == to_tuple_if_seq(row0):
                return True

    return False
