    pattern = re.compile(var1)

    # helper to get a value from a row in several common row shapes
    def _get_value(row, key):
        # dict-like
        if isinstance(row, dict):
            return row.get(key)
        # object with .get (e.g., some mapping-like rows)
        if hasattr(row, 'get'):
            try:
                return row.get(key)
            except Exception:
                pass
        # sequence-like (list/tuple) where key might be an integer index
        try:
            return row[key]
        except Exception:
            pass
        # attribute access fallback
        return getattr(row, key, None)

    # predicate used to keep rows that match
    def _matches(row):
        val = _get_value(row, var0)
        if val is None:
            return False
        return bool(pattern.search(str(val)))

    # use petp.filter if available
    if hasattr(petp, 'filter'):
        return petp.filter(df0, _matches)
    else:
        raise RuntimeError("petp.filter not found in the installed petp library.")
