def sort_table(df0, by, ascending=True, return_rows=False, rows_as='tuple'):
    """
    Sort a 2D data table (df0) by one or more columns using modim/modin's pandas-like API.

    Parameters:
    - df0: a DataFrame-like object from modim (preferred) or modin.pandas
    - by: str or list/tuple of column names (or column indices if supported)
    - ascending: bool or list/tuple of bools. If a single bool, applies to all columns.
    - return_rows: bool. If False (default), return the sorted DataFrame. If True, return rows.
    - rows_as: 'tuple' or 'dict' when return_rows=True. 'tuple' returns a list of tuples;
               'dict' returns a list of dicts (records).

    Returns:
    - Sorted DataFrame (default) or list of rows in the sorted order.
    """
    # Try to import modim first, fall back to modin.pandas
    try:
        import modim as md  # preferred if the user meant modim
        DataFrameType = md.DataFrame if hasattr(md, "DataFrame") else None
    except Exception:
        md = None
        DataFrameType = None
    if md is None:
        try:
            import modin.pandas as md  # fallback to modin
            DataFrameType = md.DataFrame
        except Exception:
            raise ImportError(
                "Could not import 'modim' or 'modin'. Please install one of them."
            )

    # Normalize 'by' to a list
    if isinstance(by, str) or not hasattr(by, '__iter__'):
        by = [by]
    else:
        by = list(by)

    if len(by) < 1:
        raise ValueError("Parameter 'by' must specify at least one column to sort by.")

    # Normalize ascending
    if isinstance(ascending, bool):
        asc = ascending
    else:
        try:
            asc = list(ascending)
        except Exception:
            raise ValueError("Parameter 'ascending' must be a bool or an iterable of bools.")
        if len(asc) != len(by):
            raise ValueError("If 'ascending' is an iterable, its length must match 'by'.")

    # Perform the sort. Use sort_values (pandas-compatible API)
    try:
        sorted_df = df0.sort_values(by=by, ascending=asc)
    except Exception as e:
        # Provide a clearer error message if sort_values fails
        raise RuntimeError(f"Sorting failed: {e}")

    # Reset index to get rows in clean order (optional but often desirable)
    try:
        sorted_df = sorted_df.reset_index(drop=True)
    except Exception:
        # If reset_index not available, ignore
        pass

    if not return_rows:
        return sorted_df

    # Return rows in requested format
    if rows_as == 'dict':
        try:
            return sorted_df.to_dict(orient='records')
        except Exception:
            # Fallback: build dicts manually
            cols = list(sorted_df.columns)
            result = []
            for row in sorted_df.itertuples(index=False, name=None):
                result.append({col: val for col, val in zip(cols, row)})
            return result
    else:
        # default: tuple rows
        try:
            return [tuple(r) for r in sorted_df.itertuples(index=False, name=None)]
        except Exception:
            # Last-resort fallback using values (may produce numpy types)
            try:
                vals = sorted_df.values
                return [tuple(row) for row in vals.tolist()]
            except Exception as e:
                raise RuntimeError(f"Could not produce row list: {e}")
