                return val.lower()
            # wrap nested dicts lazily
            if isinstance(val, dict):
                return LowercaseLazyMapping(val)
            return val

        # convenience helpers that also compute values on demand
        def keys(self):
            return self._index.keys()

        def items(self):
            for k in self:
                yield (k, self[k])

        def values(self):
            for k in self:
                yield self[k]

